import 'package:fluent_ui/fluent_ui.dart';

void main() => runApp(const MyApp());

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return FluentApp(
      title: 'Fluent Demo',
      theme: FluentThemeData(
        accentColor: Colors.blue,
      ),
      home: const HomePage(),
    );
  }
}

import 'package:fluent_ui/fluent_ui.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int index = 0;

  @override
  Widget build(BuildContext context) {
    return NavigationView(
      pane: NavigationPane(
        selected: index,
        onChanged: (i) => setState(() => index = i),
        displayMode: PaneDisplayMode.auto,
        items: [
          PaneItem(icon: const Icon(FluentIcons.home), title: const Text('홈')),
          PaneItem(icon: const Icon(FluentIcons.settings), title: const Text('설정')),
        ],
      ),
      content: NavigationBody(
        index: index,
        children: const [
          Center(child: Text('홈 화면')),
          Center(child: Text('설정 화면')),
        ],
      ),
    );
  }
}

import 'package:fluent_ui/fluent_ui.dart';

class WidgetsDemo extends StatelessWidget {
  const WidgetsDemo({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Button(
          child: const Text('기본 버튼'),
          onPressed: () {},
        ),
        const SizedBox(height: 12),
        FilledButton(
          child: const Text('강조 버튼'),
          onPressed: () {},
        ),
        const SizedBox(height: 12),
        TextBox(placeholder: '검색어 입력'),
      ],
    );
  }
}

return FluentApp(
  theme: FluentThemeData(
    brightness: Brightness.light,
    accentColor: Colors.blue,
  ),
  darkTheme: FluentThemeData(
    brightness: Brightness.dark,
    accentColor: Colors.orange,
  ),
  themeMode: ThemeMode.system,
  home: const HomePage(),
);
